inline bool row_full(const study_grid::Grid& grid, int row) noexcept {
  if (row < 0 || row >= study_grid::Grid::kRows) {
    return false;
  }
  for (int column = 0; column < study_grid::Grid::kColumns; ++column) {
    const std::optional<study_grid::Cell> cell = grid.get(row, column);
    if (!cell.has_value() || *cell != study_grid::Cell::filled) {
      return false;
    }
  }
  return true;
}

int write = study_grid::Grid::kRows - 1;
int removed = 0;
for (int read = study_grid::Grid::kRows - 1; read >= 0; --read) {
  if (row_full(grid, read)) {
    ++removed;
    continue;
  }
  if (write != read) {
    for (int column = 0; column < study_grid::Grid::kColumns; ++column) {
      const std::optional<study_grid::Cell> cell = grid.get(read, column);
      (void)grid.set(write, column, *cell);
    }
  }
  --write;
}

  // Rows 0..write still describe the vacated stack space above the surviving
  // rows, so reset them to empty. When nothing was removed, `write` is -1 and
  // this loop does not run.
  for (int row = 0; row <= write; ++row) {
    for (int column = 0; column < study_grid::Grid::kColumns; ++column) {
      (void)grid.set(row, column, study_grid::Cell::empty);
    }
  }
  return removed;
}

candidate.active_.reset(); // The locked piece now belongs to the board.
// Resolve the board before testing the next spawn.
candidate.last_cleared_ = study_lines::clear_full_rows(candidate.board_);
const auto spawn = study_catalog::make_piece(candidate.kind_);
if (!spawn) return Step::invalid;

bool piece_changed = false, board_changed = false;
int cleared_this_frame = 0;
for (unsigned i = 0; i < batch->ticks; ++i) {
    const auto result = round.tick(pending.consume());
    if (result == study_round::Step::invalid) return 1;
    const bool locked = result == study_round::Step::locked ||
                        result == study_round::Step::game_over;
    if (locked) cleared_this_frame += round.last_cleared();
    board_changed = board_changed || locked;
    piece_changed = piece_changed || locked || result == study_round::Step::moved;
    if (result == study_round::Step::game_over)
        std::puts("GAME OVER: spawn blocked; final board remains visible. Escape to exit.");
}
if (cleared_this_frame > 0)
    std::printf("cleared %d row(s) this frame\n",cleared_this_frame);
